INSERT INTO feature VALUES('coverage-evidence','checking','Coverage as replayable evidence','coverage','partial','notable',NULL,'A semantic coverage verdict the kernel replays, fed by unification: a pattern hole''s arms covered by the canonical cover and refused as undecided by name where the cover cannot be derived. A match records its cover derivation beside its decision tree, one step for each node: a `var` names a leaf''s arm, a `split` lists one column''s cases in the order of its type, and a `compose` places a derivation under a branch. A data split lists the loops its case carries after its constructors. The kernel replays the derivation at the definition''s admission: each data split re-derives its family''s constructors and loops and meets its own case, and a derivation that does not replay is refused by the step that breaks. A system of faces in the reader `.#{`, `Config.#{secure ↦ *{.port = 443, .tls = true}, addr ↦ *{.host = "localhost", .port = 443}}`, is a face cover: the type member''s face poset holds each face and the meet of each two faces, the lowering reads the meet of each two faces from it, and the checker converts each later face''s value on a meet with the value the first face fixes there, refusing a disagreement as `FixedFieldDiffers` at that value. A face poset holds up to 4,096 cells, past one machine word, its order the inclusion of the cells'' labels; a record type past that count is refused as `FacePosetPastBudget`, naming the type.','kernel-term kernel-core core-term core-checker surface-lowering surface-dispatcher theory-graded-posets','corpus/pathological/holes/pattern-hole-arms.gandr corpus/model/holes/pattern-hole-arms.gandr corpus/model/desc/record-faces.gandr corpus/model/desc/wide-face-poset.gandr corpus/pathological/desc/record-faces.gandr crates/kernel-term/src/cover/tests.rs crates/kernel-core/tests/cover.rs crates/surface-lowering/src/lower/patched/tests.rs crates/core-checker-base/src/module/tests.rs crates/core-checker-base/tests/module.rs','corpus/ledger/features/coverage-evidence.gandr','#391');
